/* ---------- Les gisements de cristaux : 3 tailles (small / medium / big).
   Stock de matériaux 1x/2x/3x et vitesse d'extraction 1x/2x/3x selon la
   taille — un drone vide donc un gisement en ~3 min 20 quelle que soit sa
   taille, mais un grand gisement rapporte 3x plus, 3x plus vite. ---------- */
const CRX = {
  ok: false, n: 0, imgs: [], mips: {},
  m: [{ hw: 1.004, gax: 0.530, gay: 0.660 },
      { hw: 0.924, gax: 0.524, gay: 0.660 },
      { hw: 1.011, gax: 0.521, gay: 0.598 }],
  w: [0.48, 0.70, 0.99], // largeur dessinée (cases), fissures comprises — réduite d'1/4 (retour propriétaire)
};
["",
"",
""].forEach((src, i) => {
  const img = new Image();
  img.onload = () => { CRX.imgs[i] = img; CRX.ok = ++CRX.n === 3; };
  img.src = "data:image/webp;base64," + src;
});
function crxImg(sz) {
  const img = CRX.imgs[sz];
  const px = CRX.w[sz] * TW * cam.z * DPR;
  const k = [180, 360, img.width].find((v) => v >= px) || img.width;
  const key = sz + ":" + k;
  let c = CRX.mips[key];
  if (!c) {
    c = CRX.mips[key] = document.createElement("canvas");
    c.width = k; c.height = Math.round(k * img.height / img.width);
    c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
  }
  return c;
}
const VART = { ok: false, imgs: [], mips: {} };
["",
""].forEach((src, i2) => {
  const img = new Image();
  img.onload = () => { VART.imgs[i2] = img; VART.ok = true; };
  img.src = "data:image/webp;base64," + src;
});
const VART_SPOTS = [[2, 4], [6, 4]]; // UNE fissure, UNE fissures (hors zones)
function vartImg(which) {
  const img = VART.imgs[which];
  if (!img) return null;
  const px = TILE.world * cam.z * DPR * 0.45;
  const size = [128, 256, img.width].find((v) => v >= px) || img.width;
  const key = which + ":" + size;
  let c = VART.mips[key];
  if (!c) {
    c = VART.mips[key] = document.createElement("canvas");
    c.width = c.height = size;
    c.getContext("2d").drawImage(img, 0, 0, size, size);
  }
  return c;
}
const CREV = { ok: false };
(function () {
  const img = new Image();
  img.onload = () => { CREV.img = img; CREV.ok = true; };
  img.src = "data:image/webp;base64,";
})();
/* Le caillou du propriétaire, semé sur le terrain libre : décor pur, il
   n'occupe rien et ne bloque aucune pose. Présence, décalage dans la case et
   taille sont déterministes (graine de la case) : le paysage ne bouge pas
   d'une session à l'autre. */
const CAI = { ok: false, hw: 0.794, mips: {} };
(function () {
  const img = new Image();
  img.onload = () => { CAI.img = img; CAI.ok = true; };
  img.src = "data:image/webp;base64,";
})();
function caiImg() {
  const px = 0.40 * TW * cam.z * DPR;
  const k = [96, 192, CAI.img.width].find((v) => v >= px) || CAI.img.width;
  let c = CAI.mips[k];
  if (!c) {
    c = CAI.mips[k] = document.createElement("canvas");
    c.width = k; c.height = Math.round(k * CAI.img.height / CAI.img.width);
    c.getContext("2d").drawImage(CAI.img, 0, 0, c.width, c.height);
  }
  return c;
}
// y a-t-il un caillou sur cette case, et où exactement ?
function caiAt(x, y) {
  if (x === SRC.x && y === SRC.y) return null;
  const info = tileAt(x, y);
  if (info.kind !== "sand") return null;
  const k = x + "," + y;
  if (montSet.has(k) || lacSet.has(k) || duneSet.has(k) || fertSet.has(k)) return null;
  if (crxSpots.has(k)) return null;
  const r = mulberry32(hash2(x, y) ^ 0x5EED);
  if (r() > 0.42) return null; // « pas mal d'endroits », pas partout
  let ox = (r() - 0.5) * 0.62, oy = (r() - 0.5) * 0.62;
  const kk = 0.60 + r() * 0.34;
  // sur la rangée de bord on garde les cailloux (le propriétaire les veut sur
  // les côtés) mais on les rentre : le décalage est forcé vers l'intérieur
  if (x === bmin()) ox = Math.abs(ox) + 0.10;
  if (x === bmax()) ox = -Math.abs(ox) - 0.10;
  if (y === bmin()) oy = Math.abs(oy) + 0.10;
  if (y === bmax()) oy = -Math.abs(oy) - 0.10;
  return { ox, oy, k: kk, f: r() < 0.5 };
}
function drawCaillou(x, y) {
  const c = caiAt(x, y);
  if (!c || !CAI.ok) return;
  const p = w2s(x + c.ox, y + c.oy), z = cam.z;
  const sw = 0.40 * c.k * TW * z, sh = sw * CAI.hw;
  ctx.save();
  plateauDiamond(); ctx.clip(); // filet de sécurité : rien ne mord sur le vide
  if (c.f) { // une case sur deux en miroir : le semis ne se répète pas
    ctx.translate(p.x, p.y); ctx.scale(-1, 1);
    ctx.drawImage(caiImg(), -sw / 2, -sh * 0.62, sw, sh);
  } else {
    ctx.drawImage(caiImg(), p.x - sw / 2, p.y - sh * 0.62, sw, sh);
  }
  ctx.restore();
}
const ROCK = { ok: false, iw: 500, ih: 363, groundY: 601 / 611 };
(function () {
  const img = new Image();
  img.onload = () => { ROCK.img = img; ROCK.ok = true; };
  img.src = "data:image/webp;base64,";
})();
